// test_tags.c - T-011: the golden vectors of tests/data/ (generated by
// tools/gen_tag_vectors.py), the broken variants that must fail cleanly, and a
// fuzz pass of 10 000 mutations per vector under ASan.
//
// Expected values are written out in full rather than computed: a test that
// recomputes the parser's arithmetic proves nothing.

#define TEST_TAGS_DIR "tests\\data\\"

typedef struct TestTagFile {
    String8 path;
    String8 bytes;
} TestTagFile;

static TestTagFile test_tags_load(Arena *arena, const char *name) {
    TestTagFile file;
    file.path = str8f(arena, "%s%s", TEST_TAGS_DIR, name);
    file.bytes = os_file_read_all(arena, file.path);
    return file;
}

// The real path a scan takes: open, head, tail, parse, fall back on the name.
static b32 test_tags_read(Arena *arena, Tags *tags, const char *name) {
    TestTagFile file = test_tags_load(arena, name);
    u8 *head = push_array(arena, u8, TAGS_BLOCK_SIZE);
    u8 *tail = push_array(arena, u8, TAGS_BLOCK_SIZE);
    String8 path = str8f(arena, "%s%s", TEST_TAGS_DIR, name);
    OsFileInfo info;
    u64 size = os_file_stat(path, &info) ? info.size : 0;
    return tags_read_file(tags, path, size, head, tail);
}

#define EXPECT_STR(field, literal) EXPECT(str8_eq((field), str8_lit(literal)))

TEST(tags_id3v23_utf16) {
    Tags tags;
    EXPECT(test_tags_read(arena, &tags, "id3v23_utf16.mp3"));
    EXPECT_STR(tags.title, "Sur le fil");
    EXPECT_STR(tags.artist, "Yann Tiersen");
    EXPECT_STR(tags.album, "Le Fabuleux Destin");
    EXPECT_STR(tags.album_artist, "Yann Tiersen");
    EXPECT_STR(tags.genre, "Soundtrack");
    EXPECT(tags.track_no == 7);
    EXPECT(tags.disc_no == 1);
    EXPECT(tags.year == 2001);
    EXPECT(tags.codec == LibCodec_MP3);
    EXPECT(tags.sample_rate == 44100);
    EXPECT(tags.channels == 2);
    EXPECT(tags.duration_ms == 78367);              // 3000 Xing frames at 44100 Hz
    EXPECT(tags.replaygain_track_db == -1856);      // -7.25 dB in 1/256 dB
    EXPECT(tags.cover_size == 512);
    EXPECT(tags.cover_hash != 0);
    EXPECT(tags.cover_offset > 10 && tags.cover_offset + 512 <= 2914);
}

