// --- the broken ones -------------------------------------------------------
// None of these may crash, none may return a half filled struct: whatever the
// parsers make of them, the fallbacks still give the row a title.
static const char *test_tags_broken[] = {
    "broken_truncated.mp3", "broken_huge_size.mp3", "broken_frame_size.mp3",
    "broken_flac.flac",     "broken_ogg.ogg",       "broken_mp4.m4a",
    "broken_wav.wav",       "broken_mp4_loop.m4a",  "broken_ape.mp3",
    "empty.mp3",            "tiny.mp3",
};

TEST(tags_broken_fail_cleanly) {
    for (u64 i = 0; i < ArrayCount(test_tags_broken); i += 1) {
        Tags tags;
        test_tags_read(arena, &tags, test_tags_broken[i]);
        EXPECT(tags.title.size != 0);               // the file name, at worst
        EXPECT(tags.text_size <= TAGS_TEXT_CAPACITY);
        EXPECT(tags.title.size <= TAGS_FIELD_MAX);
        EXPECT(tags.duration_ms < 24u * 3600u * 1000u);
        EXPECT(tags.channels <= 8);
        EXPECT(tags.sample_rate <= 768000);
    }
}

TEST(tags_text_is_canonical) {
    // Invalid UTF-8 in, replacement characters out - never the raw bytes.
    u8 buffer[64];
    u8 raw[] = {'a', 0xC3, 0x28, 'b'};
    String8 clean = tags_utf8_clean(str8(raw, sizeof(raw)), buffer, sizeof(buffer));
    EXPECT(clean.size == 6);                        // 'a' + U+FFFD + '(' + 'b'
    EXPECT(clean.str[1] == 0xEF && clean.str[2] == 0xBF && clean.str[3] == 0xBD);

    u8 latin[] = {'c', 'a', 'f', 0xE9};
    String8 utf8 = tags_latin1_to_utf8(str8(latin, sizeof(latin)), buffer, sizeof(buffer));
    EXPECT(str8_eq(utf8, str8_lit("caf\xC3\xA9")));

    EXPECT(tags_parse_gain_db(str8_lit("-7.25 dB")) == -1856);
    EXPECT(tags_parse_gain_db(str8_lit("+0.00 dB")) == 0);
    EXPECT(tags_parse_gain_db(str8_lit("junk")) == 0);
    EXPECT(str8_eq(tags_genre_by_index(0), str8_lit("Blues")));
    EXPECT(str8_eq(tags_genre_by_index(125), str8_lit("Dance Hall")));
    EXPECT(tags_genre_by_index(126).size == 0);
    EXPECT(tags_genre_by_index(9999).size == 0);
}

// --- the fuzz --------------------------------------------------------------
// 10 000 mutations of every vector. The point is not what the parser returns -
// it is that ASan sees no read outside the buffer, and that the output stays
// inside its own bounds whatever the bytes said.
#define TEST_TAGS_FUZZ 10000

static const char *test_tags_all[] = {
    "id3v23_utf16.mp3", "id3v24_unsync.mp3", "id3v22.mp3", "id3v1_only.mp3",
    "mpeg_vbri.mp3", "ape_tail.mp3", "flac.flac", "ogg_vorbis.ogg", "opus.opus",
    "mp4.m4a", "mp4_moov_last.m4a", "wav.wav", "aiff.aif",
    "broken_truncated.mp3", "broken_huge_size.mp3", "broken_frame_size.mp3",
    "broken_flac.flac", "broken_ogg.ogg", "broken_mp4.m4a", "broken_wav.wav",
    "broken_mp4_loop.m4a", "broken_ape.mp3",
};

TEST(tags_fuzz_mutations) {
    u64 parsed = 0;
    for (u64 f = 0; f < ArrayCount(test_tags_all); f += 1) {
        ArenaTemp temp = arena_temp_begin(arena);
        TestTagFile original = test_tags_load(temp.arena, test_tags_all[f]);
        if (original.bytes.size == 0) { EXPECT(0); arena_temp_end(temp); continue; }
        // The mutated copy is its own allocation: ASan puts a red zone around
        // it, so one byte past the end is a crash and not a lucky read.
        u8 *copy = push_array(temp.arena, u8, original.bytes.size);
        u64 seed = 0x9E3779B97F4A7C15ull ^ f;
        for (u64 i = 0; i < TEST_TAGS_FUZZ; i += 1) {
            mem_copy(copy, original.bytes.str, original.bytes.size);
            u64 mutations = 1 + (hash64_mix(seed++) % 4);
            for (u64 m = 0; m < mutations; m += 1) {
                u64 at = hash64_mix(seed++) % original.bytes.size;
                copy[at] = (u8)(hash64_mix(seed++) & 0xFF);
            }
            TagsFile file;
            StructZero(&file);
            file.head = str8(copy, original.bytes.size);
            file.size = original.bytes.size;

            Tags tags;
            tags_init(&tags);
            if (tags_parse(&tags, &file)) { parsed += 1; }
            // Whatever it read, the output stays canonical.
            AssertAlways(tags.text_size <= TAGS_TEXT_CAPACITY);
            AssertAlways(tags.title.size <= TAGS_FIELD_MAX);
            AssertAlways(tags.cover_hashed <= original.bytes.size);
            AssertAlways(tags.cover_offset <= original.bytes.size);
        }
        arena_temp_end(temp);
    }
    // A mutation is one byte in a few thousand: most files still parse, which
    // is what makes this fuzz reach the deep paths instead of the first check.
    EXPECT(parsed > (u64)ArrayCount(test_tags_all) * TEST_TAGS_FUZZ / 2);
}

static void test_tags_run_all(void) {
    test_report("tags\n");
    RUN(tags_id3v23_utf16);
    RUN(tags_id3v24_unsync_utf8);
    RUN(tags_id3v22);
    RUN(tags_id3v1_and_cbr);
    RUN(tags_mpeg_vbri);
    RUN(tags_ape_tail);
    RUN(tags_flac);
    RUN(tags_ogg_vorbis);
    RUN(tags_opus);
    RUN(tags_mp4);
    RUN(tags_mp4_moov_last);
    RUN(tags_wav);
    RUN(tags_aiff);
    RUN(tags_broken_fail_cleanly);
    RUN(tags_text_is_canonical);
    RUN(tags_fuzz_mutations);
}
